{"command":"cat << 'EOF' > isstd.go
package main

import (
	"fmt"
	"go/build"
)

func main() {
	fmt.Println("fmt:", isStd("fmt"))
	fmt.Println("randomdir:", isStd("randomdir"))
	fmt.Println("appengine:", isStd("appengine"))
	fmt.Println("golang.org/x/tools:", isStd("golang.org/x/tools"))
}

func isStd(path string) bool {
	p, err := build.Default.Import(path, "", build.FindOnly)
	if err != nil {
		return false
	}
	return p.Goroot
}
EOF
go run isstd.go"}

