{"command":"cat << 'EOF' > parse_mod.go
package main

import (
	"fmt"
	"io/ioutil"
	"strings"
)

func main() {
	b, _ := ioutil.ReadFile("go.mod")
	for _, line := range strings.Split(string(b), "\n") {
		if strings.HasPrefix(line, "module ") {
			fmt.Println(strings.TrimSpace(strings.TrimPrefix(line, "module ")))
			break
		}
	}
}
EOF
