{"command":"cat << 'EOF' > faststd.go
package main

import (
	"fmt"
	"go/build"
	"os"
	"path/filepath"
)

func main() {
	fmt.Println("fmt:", isStd("fmt"))
	fmt.Println("randomdir:", isStd("randomdir"))
}

func isStd(path string) bool {
	if path == "" { return false }
	// some std packages don't map directly but almost all do.
	// Actually, just check if it has a dot in the first segment!
	// Wait, we want to know if randomdir is std!
	stat, err := os.Stat(filepath.Join(build.Default.GOROOT, "src", path))
	return err == nil && stat.IsDir()
}
EOF
go build -o faststd faststd.go
time ./faststd"}

