{"command":"cat << 'EOF' > test_delete.go
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/printer"
	"go/token"
	"os"
	"golang.org/x/tools/go/ast/astutil"
)

func main() {
	src := `package main

// comment 1
import (
	// comment 2
	"fmt" // inline 1
)

func main() {}
`
	fset := token.NewFileSet()
	f, _ := parser.ParseFile(fset, "", src, parser.ParseComments)
	astutil.DeleteImport(fset, f, "fmt")
	printer.Fprint(os.Stdout, fset, f)
}
EOF
go run test_delete.go"}

