{"command":"cat << 'EOF' > test_multiple.go
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
)

func main() {
	src := `package main

// This is a comment before imports
import (
	"fmt"
)

var a = 1

// Another comment
import "math"

var b = 2
`
	fset := token.NewFileSet()
	f, _ := parser.ParseFile(fset, "", src, parser.ParseComments)

	var imports []*ast.GenDecl
	for _, decl := range f.Decls {
		if gd, ok := decl.(*ast.GenDecl); ok && gd.Tok == token.IMPORT {
			imports = append(imports, gd)
		}
	}

	if len(imports) > 0 {
		newSrc := src
		// Process from last to first to keep offsets valid
		for i := len(imports)-1; i >= 0; i-- {
			startOffset := fset.Position(imports[i].Pos()).Offset
			endOffset := fset.Position(imports[i].End()).Offset

			if i == 0 {
				newSrc = newSrc[:startOffset] + "import (\n\t\"fmt\"\n\n\t\"math\"\n)" + newSrc[endOffset:]
			} else {
				// For secondary imports, we also want to remove the trailing newline if possible, but empty string is safe.
				newSrc = newSrc[:startOffset] + newSrc[endOffset:]
			}
		}
		fmt.Println(newSrc)
	}
}
EOF
go run test_multiple.go"}

