package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"strings"
)

func main() {
	src := `package main

import "fmt"
// Doc for a
var a = 1
var b = 2
// Doc for c
var c = 3
`
	fset := token.NewFileSet()
	f, _ := parser.ParseFile(fset, "", src, parser.ParseComments)

	// Convert src to lines
	lines := strings.Split(src, "\n")

	// Collect start lines of decls (from bottom to top)
	var starts []int
	for i := len(f.Decls)-1; i >= 1; i-- {
		prevEnd := fset.Position(f.Decls[i-1].End()).Line
		currStart := fset.Position(f.Decls[i].Pos()).Line
		if currStart - prevEnd < 2 {
			starts = append(starts, currStart-1) // 0-indexed line number
		}
	}

	for _, l := range starts {
		lines = append(lines[:l], append([]string{""}, lines[l:]...)...)
	}
	fmt.Println(strings.Join(lines, "\n"))
}
EOF
go run test_blank_lines.go"}

