		return
	}
	if *versionOnlyFlag {
		fmt.Println("3.0.0-20260303205914-9926ea38658f")
		return
	}

	orderList := strings.Split(*importsOrder, ",")
	if len(orderList) < 4 {
		flag.Usage()
		log.Fatal("use default at least 4 parameters to sort groups of your imports: \"std,general,company,project\"")
	}

	args := flag.Args()
	if *filePath != "" {
		args = append(args, *filePath)
	}

	if len(args) == 0 {
		flag.Usage()
