	}

	args := flag.Args()
	if *filePath != "" {
		args = append(args, *filePath)
	}

	if len(args) == 0 {
		flag.Usage()
		return
	}

	log.Printf("Paths: %v\n", args)

	for _, arg := range args {
		log.Printf("Processing %s\n", arg)
		path := arg
		if arg == "./..." {
			path = "."
			*recursive = true
		}

		projName := getProjectName(path)
		if projName == "" && *projectName == "" {
			flag.Usage()
			log.Fatalf("Could not determine project name for path %s: open go.mod: no such file or directory", path)
		}
		if *projectName == "" {
			*projectName = projName
		}

		processPath(path)
	}

	if *setExitStatus && hasDiff {
		os.Exit(1)
	}
}

func getProjectName(path string) string {
	dir := path
	stat, err := os.Stat(dir)
	if err == nil && !stat.IsDir() {
		dir = filepath.Dir(dir)
	} else if err != nil {
		dir = filepath.Dir(dir)
	}
	dir, _ = filepath.Abs(dir)
	for {
		b, err := ioutil.ReadFile(filepath.Join(dir, "go.mod"))
		if err == nil {
			for _, line := range strings.Split(string(b), "\n") {
				if strings.HasPrefix(line, "module ") {
					return strings.TrimSpace(strings.TrimPrefix(line, "module "))
				}
			}
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			break
		}
		dir = parent
	}
	return ""
}

func processPath(path string) {
	stat, err := os.Stat(path)
	if err != nil {
		log.Printf("Failed to fix file: %v", err)
		return
	}

	if stat.IsDir() {
		if !*recursive && path != "." {
			return
		}
		err = filepath.Walk(path, func(p string, info os.FileInfo, err error) error {
			if err != nil { return nil }
			if info.IsDir() { return nil }
			if !strings.HasSuffix(info.Name(), ".go") { return nil }
			if shouldExclude(p) { return nil }
			processFile(p)
			return nil
		})
		if err != nil {
			log.Printf("Failed to fix file: %v", err)
		}
	} else {
		if strings.HasSuffix(stat.Name(), ".go") && !shouldExclude(path) {
			processFile(path)
		}
	}
}

func shouldExclude(path string) bool {
	if *excludes == "" {
		return false
	}
	for _, ex := range strings.Split(*excludes, ",") {
		ex = strings.TrimSpace(ex)
		if strings.Contains(path, ex) { return true }
		match, _ := filepath.Match(ex, filepath.Base(path))
		if match { return true }
	}
	return false
}

func processFile(path string) {
	b, err := ioutil.ReadFile(path)
	if err != nil { return }
	src := string(b)

	if !*applyToGeneratedFiles {
		if strings.Contains(src, "// Code generated") {
			lines := strings.SplitN(src, "\n", 10)
			for _, l := range lines {
				if strings.HasPrefix(strings.TrimSpace(l), "// Code generated") {
					return
				}
			}
		}
	}

	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, path, src, parser.ParseComments)
	if err != nil { return }

	var importBlocks []*ast.GenDecl
	var specs []*ast.ImportSpec
	for _, decl := range f.Decls {
		if gd, ok := decl.(*ast.GenDecl); ok && gd.Tok == token.IMPORT {
			isOnlyC := true
			for _, spec := range gd.Specs {
				ispec := spec.(*ast.ImportSpec)
				if ispec.Path.Value != `"C"` {
					isOnlyC = false
					break
				}
			}
			if isOnlyC { continue }
			importBlocks = append(importBlocks, gd)
			for _, spec := range gd.Specs {
				ispec := spec.(*ast.ImportSpec)
				if ispec.Path.Value != `"C"` {
					specs = append(specs, ispec)
				}
			}
		}
	}

	if len(importBlocks) > 0 {
		newSpecs, err := fixImports(fset, f, path, specs)
		if err != nil {
			fmt.Fprintln(os.Stderr, err.Error())
			log.Println("Failed to fix file: package has an errors")
			return
		}

		importStr := buildImportBlock(newSpecs)
		newSrc := src
		for i := len(importBlocks) - 1; i >= 0; i-- {
			gd := importBlocks[i]
			start := fset.Position(gd.Pos()).Offset
			end := fset.Position(gd.End()).Offset
			if i == 0 {
				newSrc = newSrc[:start] + importStr + newSrc[end:]
			} else {
				newSrc = newSrc[:start] + newSrc[end:]
			}
		}

		formatted, err := format.Source([]byte(newSrc))
		if err == nil {
			newSrc = string(formatted)
		}

		if *formatFlag {
			newSrc = applyFormatBlankLines([]byte(newSrc), fset)
			formatted, err = format.Source([]byte(newSrc))
			if err == nil {
				newSrc = string(formatted)
			}
		}

		if src != newSrc {
			hasDiff = true
			if *listDiff {
				absPath, _ := filepath.Abs(path)
				fmt.Println(absPath)
			}
			if *outputOpt == "write" || *outputOpt == "file" {
				ioutil.WriteFile(path, []byte(newSrc), 0644)
			} else if *outputOpt == "stdout" {
				fmt.Print(newSrc)
			}
		} else if *outputOpt == "stdout" && !*listDiff {
			fmt.Print(newSrc)
		}
	} else if *formatFlag {
		formatted, err := format.Source(b)
		if err == nil {
			newSrc := applyFormatBlankLines(formatted, fset)
			formatted2, err2 := format.Source([]byte(newSrc))
			if err2 == nil {
				newSrc = string(formatted2)
			}
			if src != newSrc {
				hasDiff = true
				if *listDiff {
					absPath, _ := filepath.Abs(path)
					fmt.Println(absPath)
				}
				if *outputOpt == "write" || *outputOpt == "file" {
					ioutil.WriteFile(path, []byte(newSrc), 0644)
				} else if *outputOpt == "stdout" {
					fmt.Print(newSrc)
				}
			} else if *outputOpt == "stdout" && !*listDiff {
				fmt.Print(newSrc)
			}
		}
	}
}

func applyFormatBlankLines(src []byte, fset *token.FileSet) string {
	f, err := parser.ParseFile(fset, "", string(src), parser.ParseComments)
	if err != nil { return string(src) }
	lines := strings.Split(string(src), "\n")
	for i := len(f.Decls) - 1; i >= 1; i-- {
		prevEnd := fset.Position(f.Decls[i-1].End()).Line
		currPos := f.Decls[i].Pos()
		if gd, ok := f.Decls[i].(*ast.GenDecl); ok && gd.Doc != nil {
			currPos = gd.Doc.Pos()
		} else if fd, ok := f.Decls[i].(*ast.FuncDecl); ok && fd.Doc != nil {
			currPos = fd.Doc.Pos()
		}
		currStart := fset.Position(currPos).Line
		if currStart-prevEnd < 2 {
			l := currStart - 1
			lines = append(lines[:l], append([]string{""}, append([]string(nil), lines[l:]...)...)...)
		}
	}
	return strings.Join(lines, "\n")
}

func isStd(path string) bool {
	stat, err := os.Stat(filepath.Join(build.Default.GOROOT, "src", path))
	return err == nil && stat.IsDir()
}

type ParsedImport struct {
	Spec    *ast.ImportSpec
	Path    string
	Alias   string
	PkgName string
	Group   string
}

func getPackageName(path string) (string, error) {
	if isStd(path) {
		return filepath.Base(path), nil
	}
	cmd := exec.Command("go", "list", "-f", "{{.Name}}", path)
	out, err := cmd.CombinedOutput()
	if err != nil {
		return "", fmt.Errorf("%s", string(out))
	}
	return strings.TrimSpace(string(out)), nil
}

func fixImports(fset *token.FileSet, f *ast.File, filePath string, specs []*ast.ImportSpec) ([]*ast.ImportSpec, error) {
	usedIdents := make(map[string]bool)
	ast.Inspect(f, func(n ast.Node) bool {
		switch node := n.(type) {
		case *ast.GenDecl:
			if node.Tok == token.IMPORT { return false }
		case *ast.Ident:
			usedIdents[node.Name] = true
		}
		return true
	})

	var parsed []ParsedImport
	for _, spec := range specs {
		path := strings.Trim(spec.Path.Value, `"`)
		alias := ""
		if spec.Name != nil {
			alias = spec.Name.Name
		}

		pkgName := ""
		if (*rmUnused || *setAlias) && alias == "" && path != "C" {
			name, err := getPackageName(path)
			if err != nil {
				pos := fset.Position(spec.Pos())
				firstLine := strings.Split(err.Error(), "\n")[0]
				return nil, fmt.Errorf("%s:%d:%d: %s", filePath, pos.Line, pos.Column, firstLine)
			}
			pkgName = name
		}

		if *setAlias && alias == "" && pkgName != "" && path != "C" {
			base := filepath.Base(path)
			if base != pkgName {
				alias = pkgName
				spec.Name = &ast.Ident{Name: alias}
			}
		}

		if *rmUnused {
			isUsed := true
			if alias == "." || alias == "_" || path == "C" {
				isUsed = true
			} else if alias != "" {
				isUsed = usedIdents[alias]
			} else {
				isUsed = usedIdents[pkgName]
			}
			if !isUsed {
				continue
			}
		}

		isProj := false
		if *projectName != "" {
			if strings.HasPrefix(path, *projectName+"/") || path == *projectName {
				isProj = true
			}
		}

		isComp := false
		if *companyPrefixes != "" {
			for _, cp := range strings.Split(*companyPrefixes, ",") {
				cp = strings.TrimSpace(cp)
				if cp != "" && (strings.HasPrefix(path, cp+"/") || path == cp) {
					isComp = true
					break
				}
			}
		}

		isStdPkg := isStd(path)

		group := "general"
		orderList := strings.Split(*importsOrder, ",")
		for _, g := range orderList {
			g = strings.TrimSpace(g)
			if g == "blanked" && alias == "_" { group = g; break }
			if g == "dotted" && alias == "." { group = g; break }
			if g == "std" && isStdPkg { group = g; break }
			if g == "project" && isProj { group = g; break }
			if g == "company" && isComp { group = g; break }
		}

		parsed = append(parsed, ParsedImport{
			Spec:  spec,
			Path:  path,
			Alias: alias,
			Group: group,
		})
	}

	var out []*ast.ImportSpec
	orderList := strings.Split(*importsOrder, ",")
	for _, g := range orderList {
		g = strings.TrimSpace(g)
		for _, p := range parsed {
			if p.Group == g {
				out = append(out, p.Spec)
			}
		}
	}
	for _, p := range parsed {
		if p.Group == "general" {
			found := false
			for _, g := range orderList {
				if strings.TrimSpace(g) == "general" { found = true }
			}
			if !found { out = append(out, p.Spec) }
		}
	}

	return out, nil
}

func buildImportBlock(specs []*ast.ImportSpec) string {
	if len(specs) == 0 { return "" }
	var buf bytes.Buffer
	buf.WriteString("import (\n")

	var groups [][]*ast.ImportSpec
	orderList := strings.Split(*importsOrder, ",")
	groupMap := make(map[string][]*ast.ImportSpec)
	for _, spec := range specs {
		path := strings.Trim(spec.Path.Value, `"`)
		alias := ""
		if spec.Name != nil { alias = spec.Name.Name }

		isProj := false
		if *projectName != "" && (strings.HasPrefix(path, *projectName+"/") || path == *projectName) {
			isProj = true
		}
		isComp := false
		if *companyPrefixes != "" {
			for _, cp := range strings.Split(*companyPrefixes, ",") {
				cp = strings.TrimSpace(cp)
				if cp != "" && (strings.HasPrefix(path, cp+"/") || path == cp) { isComp = true; break }
			}
		}
		isStdPkg := isStd(path)

		g := "general"
		for _, ol := range orderList {
			ol = strings.TrimSpace(ol)
			if ol == "blanked" && alias == "_" { g = ol; break }
			if ol == "dotted" && alias == "." { g = ol; break }
			if ol == "std" && isStdPkg { g = ol; break }
			if ol == "project" && isProj { g = ol; break }
			if ol == "company" && isComp { g = ol; break }
		}
		groupMap[g] = append(groupMap[g], spec)
	}

	for _, ol := range orderList {
		ol = strings.TrimSpace(ol)
		if g, ok := groupMap[ol]; ok && len(g) > 0 {
			groups = append(groups, g)
			delete(groupMap, ol)
		}
	}
	if g, ok := groupMap["general"]; ok && len(g) > 0 {
		groups = append(groups, g)
	}

	for i, g := range groups {
		if i > 0 { buf.WriteString("\n") }

		if *separateNamed {
			var unnamed, named []*ast.ImportSpec
			for _, s := range g {
				if s.Name != nil && s.Name.Name != "_" && s.Name.Name != "." {
					named = append(named, s)
				} else {
					unnamed = append(unnamed, s)
				}
			}
			sortSpecs(unnamed)
			sortSpecs(named)
			for _, s := range unnamed {
				buf.WriteString(formatSpec(s) + "\n")
			}
			if len(unnamed) > 0 && len(named) > 0 {
				buf.WriteString("\n")
			}
			for _, s := range named {
				buf.WriteString(formatSpec(s) + "\n")
			}
		} else {
			sortSpecs(g)
			for _, s := range g {
				buf.WriteString(formatSpec(s) + "\n")
			}
		}
	}

	buf.WriteString(")")
	return buf.String()
}

func sortSpecs(specs []*ast.ImportSpec) {
	sort.Slice(specs, func(i, j int) bool {
		return strings.Trim(specs[i].Path.Value, `"`) < strings.Trim(specs[j].Path.Value, `"`)
	})
}

func formatSpec(s *ast.ImportSpec) string {
	str := "\t"
	if s.Name != nil {
		str += s.Name.Name + " "
	}
	str += s.Path.Value
	if s.Comment != nil {
		str += " " + s.Comment.List[0].Text
	}
	return str
}
